function main({ summary, facts_text, angle, level, gist, avoid_words, facts_raw }) {
  /* ── 大意骨架统一（2026-09-20）─────────────────────────────────────
     4 档统一以 gist 的 12 条为段落骨架，facts 退化为「高档细节池」。
     事实卡的归属由 ① nodeFact 标注的 `gist` 字段给出（1–12），这里派生：
       gist_fact_map : 12 项，第 i 项 = 挂靠第 i 条大意的事实卡编号数组
       gist_lines    : 12 条大意的编号文本（给低档当段落骨架）
       level_material_b1 / _b2p : 大意骨架 + 每条下挂自己那些细节
     容错铁律（与全链路一致）：字段缺失 / 类型不对 → 一律降级为空，绝不抛错。 */
  const GN = 12;
  const buildGistSkeleton = (rawFact, fallbackText) => {
    const fo = (rawFact && typeof rawFact === 'object') ? rawFact : {};
    const fl = Array.isArray(fo.facts) ? fo.facts : [];
    const gl = Array.isArray(fo.gist) ? fo.gist : [];
    const txt = (x) => (typeof x === 'string' ? x : String((x && (x.en || x.zh)) || ''));
    const facts = fl.map((f) => ({
      en: String((f && f.en) || '').trim() || String((f && f.zh) || '').trim(),
      g: parseInt(f && f.gist, 10)
    })).filter((f) => f.en);
    /* 归属号纠偏：非整数 / 越界 / 缺省 → 按「已用最大号 + 1」顺序回填。
       绝不能因为模型漏标就把事实丢掉 —— 丢了细节，高档就写不出东西。 */
    let cursor = 1;
    facts.forEach((f) => {
      if (!(f.g >= 1 && f.g <= GN)) { f.g = cursor; }
      cursor = Math.max(cursor, f.g + 1);
    });
    /* 回填号越过 GN 时（模型**整体漏标**、而事实卡又多于 12 张）折回 1..GN 轮转。
       实测：14 张卡全部漏标 → 顺序回填成 1..14，第 13/14 张会因越界从骨架里消失。
       号溢出绝不能变成「事实卡被丢掉」。 */
    facts.forEach((f) => { if (f.g > GN) { f.g = ((f.g - 1) % GN) + 1; } });
    const map = [];
    for (let i = 1; i <= GN; i++) {
      map.push(facts.map((f, ix) => (f.g === i ? ix + 1 : 0)).filter(Boolean));
    }
    const gist = [];
    for (let i = 0; i < GN; i++) {
      const g = gl[i] || {};
      gist.push({ en: txt(g.en !== undefined ? g.en : g).trim(), zh: String((g && g.zh) || '').trim() });
    }
    /* 素材丢失兜底（只防事故，不改正常路径）：
       既没有 facts 也没有 gist 时（GEN 被单独调用、上游没传 facts_raw ——
       存量缓存里就有这种旧结果），若给了 fallbackText 就用它的编号行当骨架、
       高档材料退回该原文。绝不因为上游少传一个字段就让 B1/B2+「无米下锅」
       去凭空编内容 —— 那种塌陷没有任何报错，是最危险的一种。 */
    if (!facts.length && !gist.some((g) => g.en || g.zh)) {
      const rows = String(fallbackText || '').split(/\r?\n/)
        .map((s) => s.replace(/^\s*\d+\s*[.、)]\s*/, '').trim()).filter(Boolean);
      if (rows.length) {
        const fb = rows.join('\n');
        return {
          gist_fact_map: JSON.stringify(map),
          gist_lines: rows.map((t, ix) => (ix + 1) + '. ' + t).join('\n'),
          level_material_b1: fb,
          level_material_b2p: fb
        };
      }
    }
    const lines = [];
    for (let i = 1; i <= GN; i++) {
      lines.push('【大意 ' + i + '】' + (gist[i - 1].en || gist[i - 1].zh || '（本条无对应素材）'));
      map[i - 1].forEach((n) => lines.push('    细节：' + facts[n - 1].en));
    }
    const material = lines.join('\n');
    return {
      gist_fact_map: JSON.stringify(map),
      gist_lines: gist.map((g, i) => (i + 1) + '. ' + (g.en || g.zh)).join('\n'),
      level_material_b1: material,
      level_material_b2p: material
    };
  };
  /* GEN 可能被单独调用（不经抽取链路）而没传 facts_raw —— 必须容错，绝不抛错。 */
  const parseFact = (t) => {
    try {
      const s = String(t || '').replace(/<think>[\s\S]*?<\/think>/g, '').replace(/```json|```/g, '');
      const m = s.match(/\{[\s\S]*\}/);
      if (!m) return {};
      try { return JSON.parse(m[0]); } catch (e) {
        try { return JSON.parse(m[0].replace(/,(\s*[\]}])/g, '$1')); } catch (e2) { }
      }
    } catch (e) { }
    return {};
  };
  const GM = buildGistSkeleton(parseFact(facts_raw), facts_text);
  const normLevel = (v) => {
    let s = String(v || '').trim().toUpperCase().replace(/\s+/g, '').replace(/[_-]/g, '.').replace(/档/g, '');
    s = s.replace(/^B2PLUS/, 'B2').replace(/^B2P/, 'B2');
    const AL = {
      'A1':'A1','A2':'A2','B1':'B1','B2':'B2',
      'A1.1':'A1','A1.2':'A1','A1.3':'A1',
      'A2.1':'A2','A2.2':'A2','A2.3':'A2',
      'B1.1':'B1','B1.2':'B1','B1.3':'B1',
      'B2.1':'B2','B2.2':'B2','B2.3':'B2',
      'B2+.1':'B2','B2+.2':'B2','B2+.3':'B2',
      'C1':'B2'
    };
    if (AL[s]) return AL[s];
    const m = s.match(/^(A1|A2|B1|B2\+?)/);
    if (m) { return m[1] === 'B2+' ? 'B2' : m[1]; }
    return 'B1';
  };
  /* 超纲词回灌（2026-09-20）：前端把上一稿每档的超纲词按档打包成 JSON 传进来。
     容错原则 —— 非 JSON、缺字段、类型不对，一律当空处理，绝不抛错中断生成。 */
  let av = {};
  try { const o = JSON.parse(avoid_words || '{}'); if (o && typeof o === 'object') av = o; } catch (e) { }
  const fmtAvoid = (a) => (Array.isArray(a) && a.length)
    ? (a.join(', ') + '（共 ' + a.length + ' 个）')
    : '（本轮无 —— 上一稿本档已达标，请保持同样的用词水平）';
  const lv = normLevel(level);
  const big = lv;
  return {
    summary: String(summary || 'x'),
    facts_text: String(facts_text || ''),
    /* gist 为空时退回 facts_text：GEN 可能被单独调用（不经抽取链路）而没传 gist，
       此时低档生成不应拿不到素材，宁可退回细节事实也不要产出空文。 */
    gist: String(gist || '').trim() || String(facts_text || ''),    /* 4 档统一骨架：低档直接用 gist_lines（= gist，加了编号口径归一），高档用挂细节的版本 */
    gist_fact_map: GM.gist_fact_map,
    gist_lines: GM.gist_lines,
    level_material_b1: GM.level_material_b1,
    level_material_b2p: GM.level_material_b2p,
    level: lv,
    level_big: big,
    angle: String(angle || ''),
    sensitive: 'S3 / ok', sens_level: 'S3', sens_action: 'ok', sens_reason: '',
    /* 空值必须给明确文案：渲染成空字符串的话，提示词里会剩下一句
       「必须换成更简单的表达：（空）」的断头话，模型无从判断这是「没有」还是「漏传」。 */
    avoid_a1: fmtAvoid(av.A1), avoid_a2: fmtAvoid(av.A2),
    avoid_b1: fmtAvoid(av.B1), avoid_b2: fmtAvoid(av.B2)
  };
}

function main({ style }) {
  const STYLES = {
    default: "Neutral, clear, natural expository prose — the platform's standard graded-reading style, without imitating a specific author.",
    hemingway: "Ernest Hemingway: short declarative sentences, few adjectives, concrete nouns and action verbs, understated emotion (iceberg theory).",
    austen: "Jane Austen: elegant, witty prose with keen social observation and ironic precision; polished, ironic and precise.",
    ohenry: "O. Henry: warm humor, vivid characters and a surprising ironic twist at the end.",
    twain: "Mark Twain: colloquial, humorous and lightly satirical; down-to-earth language, witty observations and folksy charm.",
    dickens: "Charles Dickens: rich narrative with vivid characters, social observation and a touch of warmth and humor.",
    orwell: "George Orwell: clear, plain, incisive prose; direct and morally serious, with concrete imagery.",
    shakespeare: "William Shakespeare: elevated, rhetorical and lyrical; rich in imagery, metaphor and rhythm."
  };
  const key = String(style || '').toLowerCase();
  const base = STYLES[key] || STYLES.default;
  const instruction = base + " Keep all facts, names, numbers and the required structure (title, paragraphs, glossary) unchanged — only the writing style differs. Adapt sentence length and vocabulary to the target CEFR level.";
  return { style_key: (key in STYLES) ? key : 'default', style_instruction: instruction };
}

