function main({ articles_json, plain_json, factcard, identity, map_basis, align_map, para_count, para_clean_count }) {
  const SPEC = {
    A1: [128, 172, -1000, 400, 6, 9],
    A2: [204, 276, 400, 750, 10, 13],
    B1: [323, 437, 750, 1050, 14, 17],
    B2: [468, 632, 1050, 1350, 18, 24]
  };
  const LABEL = { A1: 'A1-', A2: 'A2', B1: 'B1', B2: 'B2+' };
  const ALL = ['A1','A2','B1','B2'];
  const words = (t) => (String(t || '').match(/[A-Za-z0-9'-]+/g) || []).length;
  const JS = (t, d) => { try { const v = JSON.parse(t || ''); return (v && typeof v === 'object') ? v : d; } catch (e) { return d; } };
  const body = JS(plain_json, {});
  const full = JS(articles_json, {});
  /* 每档的引用基准：'fact' = 用完整事实卡生成（B1/B2+）；'gist' = 用不含数字的大意拍生成（A1/A2）。
     这个分流是必须的 —— 低档按设计就不该出现素材数字，用高档口径去校验会系统性误判。 */
  const BASISOBJ = JS(map_basis, {});

  /* 蓝思估算：est = 45×平均句长 + 1500×长词占比(≥7字符) − 350
     系数由 12 档真实生成文本对目标区间做最小二乘标定得到（RMSE ≈ 45L，覆盖 100–1300L）。
     仍非 MetaMetrics 官方值，仅作档位一致性参考。 */
  const estLexile = (t) => {
    const ws = String(t || '').match(/[A-Za-z'-]+/g) || [];
    if (!ws.length) return 0;
    const n = ws.length;
    const lng = ws.filter((w) => w.length >= 7).length;
    const st = Math.max(1, (String(t).match(/[.!?]+/g) || []).length);
    return Math.round(45 * (n / st) + 1500 * (lng / n) - 350);
  };

  const validate = (key, article) => {
    const checks = [], fails = [];
    const [lo, hi, lxlo, lxhi, slo, shi] = SPEC[key];
    const basis = BASISOBJ[key] === 'gist' ? 'gist' : 'fact';
    const wc = words(article);
    /* 长度闸门（2026-09-18 收紧）：越界即不合格，不再保留「低于下限 25% 仍放行」的容差。
       区间内再按与靶心（区间中点）的距离区分 pass / warn —— 产出应尽量贴中点，而不是贴下限。 */
    const tgt = Math.round((lo + hi) / 2);
    if (wc < lo || wc > hi) {
      fails.push('长度校验: 词数 ' + wc + '，' + LABEL[key] + ' 应为 ' + lo + '-' + hi);
      checks.push({ name: '长度校验', status: 'fail', detail: wc + ' 词（越界，靶心 ' + tgt + '）' });
    } else {
      const okIn = Math.abs(wc - tgt) <= (hi - lo) * 0.2;
      checks.push({ name: '长度校验', status: okIn ? 'pass' : 'warn',
        detail: wc + ' 词（' + lo + '-' + hi + '，靶心 ' + tgt + '）' });
    }
    const st = Math.max(1, (String(article || '').match(/[.!?]+/g) || []).length);
    const msl = wc / st;
    if (msl < slo * 0.75 || msl > shi * 1.3) {
      fails.push('句长校验: 平均句长 ' + msl.toFixed(1) + ' 词，' + LABEL[key] + ' 应为 ' + slo + '-' + shi);
      checks.push({ name: '句长校验', status: 'fail', detail: msl.toFixed(1) + ' 词/句' });
    } else {
      const okIn = (msl >= slo * 0.9 && msl <= shi * 1.1);
      checks.push({ name: '句长校验', status: okIn ? 'pass' : 'warn', detail: msl.toFixed(1) + ' 词/句（' + slo + '-' + shi + '）' });
    }
    const lex = estLexile(article);
    const pLo = (lxlo > 0 ? lxlo * 0.80 : lxlo) - 80, pHi = lxhi * 1.20 + 80;
    if (lex < pLo || lex > pHi) {
      fails.push('蓝思校验: 估算 ' + lex + 'L，' + LABEL[key] + ' 应为 ' + (lxlo > 0 ? lxlo + '-' + lxhi : 'BR-' + lxhi) + 'L');
      checks.push({ name: '蓝思校验', status: 'fail', detail: '估算 ' + lex + 'L' });
    } else {
      const okIn = (lxlo <= 0 || lex >= lxlo * 0.90) && lex <= lxhi * 1.10;
      checks.push({ name: '蓝思校验', status: okIn ? 'pass' : 'warn', detail: '估算 ' + lex + 'L（' + (lxlo > 0 ? lxlo + '-' + lxhi : 'BR-' + lxhi) + 'L）' });
    }
    const sensWords = ['分裂', '血腥', '赌博', '毒品', '色情', '种族歧视', '遇难者隐私'];
    const hits = sensWords.filter((w) => String(article || '').includes(w));
    if (hits.length) {
      fails.push('敏感排查: 命中 ' + hits.join('/'));
      checks.push({ name: '敏感排查', status: 'fail', detail: hits.join('/') });
    } else {
      checks.push({ name: '敏感排查', status: 'pass', detail: '' });
    }
    /* 语法粗筛（轻量，仅 warn 不做 fail）：A1- 完全禁用被动与完成时，用保守表面形式检测。
       只抓 A1 的明显违规，A2/B1 的被动/完成时是「有条件允许」，正则判不了条件故不粗筛。 */
    if (key === 'A1') {
      const passive = String(article || '').match(/\b(is|are|was|were|been|being)\s+\w{3,}(ed|en)\b/gi) || [];
      const perfect = String(article || '').match(/\b(has|have|had)\s+\w{3,}(ed|en)\b/gi) || [];
      const gw = [];
      if (passive.length) gw.push('疑似被动 ' + passive.slice(0, 3).join(' / '));
      if (perfect.length) gw.push('疑似完成时 ' + perfect.slice(0, 3).join(' / '));
      if (gw.length) {
        checks.push({ name: '语法粗筛', status: 'warn', detail: gw.join('；') });
      } else {
        checks.push({ name: '语法粗筛', status: 'pass', detail: '' });
      }
    } else {
      checks.push({ name: '语法粗筛', status: 'pass', detail: '非 A1 不粗筛' });
    }
    let factNums = [];
    try { factNums = (JSON.stringify(JSON.parse(factcard || '{}')).match(/\d[\d,.]*%?/g) || []).slice(0, 6); } catch (e) { }
    /* 低档（gist 基准）按设计只用「不含数字与专名的大意拍」生成，所以「素材数字未出现」
       是**预期结果**，不是缺陷 —— 用高档口径判它 fail 会让 A1/A2 六档被系统性误判。
       低档真正该防的是相反方向：凭空编出数字。所以这里改成「出现数字就告警」。 */
    if (basis === 'gist') {
      const anyNum = String(article || '').match(/\d[\d,.]*%?/g) || [];
      if (anyNum.length) {
        checks.push({ name: '事实一致性', status: 'warn',
          detail: '低档出现数字 ' + anyNum.slice(0, 4).join('/') + '（本档按设计不含数字，请核实来源）' });
      } else {
        checks.push({ name: '事实一致性', status: 'pass', detail: '低档无数字（符合大意拍口径）' });
      }
    } else {
      const missNums = factNums.filter((n) => !String(article || '').includes(n));
      if (factNums.length && missNums.length === factNums.length) {
        fails.push('事实一致性: 事实卡关键数字未出现');
        checks.push({ name: '事实一致性', status: 'fail', detail: '' });
      } else {
        checks.push({ name: '事实一致性', status: 'pass', detail: factNums.length ? (factNums.length - missNums.length) + '/' + factNums.length + ' 数字命中' : '' });
      }
    }
    const placeholders = /(TBD|TODO|\{f\d+\}|XXX|\(EMPTY\))/i.test(String(article || ''));
    const zh = (String(article || '').match(/[\u4e00-\u9fff]/g) || []).length;
    /* 语言闸门必须能区分三种截然不同的成因，否则人工审核会被误导：
       (a) 残留占位符；
       (b) 生词表被当成段落混进了正文数组（实测过，见 docs/11）；
       (c) 模型整篇输出中文（实测短素材 S2 的 B1.3 首跑：JSON 合法、段数正确、正文却全中文）。
       (c) 在聚合层已把含中文的段丢弃，所以走到这里通常表现为「正文为空」。 */
    if (!String(body[key] || '').trim()) {
      fails.push('语言纯净度: 该档正文为空（模型未产出英文段落，或产出被判为非英文后丢弃）→ 需重新生成');
      checks.push({ name: '语言纯净度', status: 'fail', detail: '正文为空 / 非英文产出' });
    } else if (placeholders || zh > 5) {
      const zhLines = String(article || '').match(/[^\n]*[\u4e00-\u9fff][^\n]*/g) || [];
      const snippet = zhLines.slice(0, 3).map((s) => s.trim().slice(0, 36)).join(' ｜ ');
      const zhHeavy = (zh > 30 && zh > wc * 2);
      fails.push('语言纯净度: ' + (placeholders
        ? '含占位符'
        : (zhHeavy
          ? '模型未输出英文（中文 ' + zh + ' 字 / 英文 ' + wc + ' 词）→ 需重新生成'
          : '正文段落疑似混入生词表/中文 ' + zh + ' 字 → ' + snippet)));
      checks.push({ name: '语言纯净度', status: 'fail',
        detail: placeholders ? '占位符' : (zhHeavy ? '整篇非英文（' + zh + ' 中文字）' : '疑似生词表混入：' + snippet) });
    } else {
      checks.push({ name: '语言纯净度', status: 'pass', detail: '' });
    }
    /* 自然度粗筛（v2 · 2026-09-20，只 warn 不 fail）—— 针对实测「翻译腔」的可机械判定症状：
       ① 段内原样重复同一名词短语（实测 A2 首段 "good family help" 说两遍）；
       ② 已知的中式搭配硬凑（"sleep at bad times" 这类「介词 + 好/坏 + 时间」结构）；
       ③ 收尾套话过量（"In the end," 一篇里出现两次以上）。
       只告警不判 fail —— 自然度的最终判定权在教研，这里只负责把可疑项摆到审核台上。
       ⚠️ 不要往这里加需要语义理解的规则（那类问题交给 ⑨ 大意复核 + 人工审核）。 */
    {
      const nat = [];
      /* 取一句话里的「内容词对」（2 词窗口，剔除功能词） */
      const bgOf = (s) => {
        const ws = String(s || '').toLowerCase().replace(/[^a-z\s']/g, ' ').split(/\s+/).filter(Boolean);
        const out = [];
        for (let i = 0; i < ws.length - 1; i++) {
          if (STOP[ws[i]] || STOP[ws[i + 1]]) continue;
          const g = ws[i] + ' ' + ws[i + 1];
          if (out.indexOf(g) < 0) out.push(g);
        }
        return out;
      };
      /* 功能词表：只统计「内容词对」。必须够全 —— 实测漏掉助动词时会报出
         「句 22-23 重复「people should」」这类**正常写作**的噪音（v2 首跑实测），
         噪音一多这条 warn 就没人看了。 */
      const STOP = { the: 1, a: 1, an: 1, of: 1, to: 1, in: 1, on: 1, at: 1, and: 1, or: 1,
        for: 1, with: 1, is: 1, are: 1, was: 1, were: 1, be: 1, been: 1, being: 1, am: 1,
        it: 1, its: 1, this: 1, that: 1, these: 1, those: 1, they: 1, them: 1, their: 1,
        he: 1, she: 1, him: 1, his: 1, her: 1, you: 1, your: 1, we: 1, us: 1, our: 1,
        i: 1, me: 1, my: 1, as: 1, by: 1, from: 1, but: 1, not: 1, no: 1,
        do: 1, does: 1, did: 1, can: 1, may: 1, might: 1, will: 1, would: 1, could: 1,
        should: 1, must: 1, has: 1, have: 1, had: 1, more: 1, most: 1, much: 1, many: 1,
        very: 1, also: 1, than: 1, then: 1, when: 1, where: 1, why: 1, how: 1, who: 1,
        which: 1, what: 1, if: 1, so: 1, such: 1, other: 1, another: 1, same: 1,
        into: 1, out: 1, up: 1, down: 1, over: 1, after: 1, before: 1, between: 1,
        during: 1, while: 1, because: 1, although: 1, since: 1, until: 1, about: 1,
        there: 1, here: 1 };
      /* 🔴 v1 的教训（实测）：v1 是「先按换行切段，再在同一段内找重复」，但
         **不能假定 body[key] 里一定有换行** —— v1 上线实测把整篇当成一段，于是报出
         「第 1 段内重复：people live / family help / daily habits」这类**全篇级误报**
         （主题词在同一篇里重复出现是正常的英语写法）。
         ⇒ 判据必须对分段方式不敏感：改为**按句子切分 + 只看相邻句对**，有没有换行都成立。 */
      const sents = String(body[key] || '').split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
      const rep = [];
      for (let i = 0; i < sents.length - 1; i++) {
        const a = bgOf(sents[i]), b = bgOf(sents[i + 1]);
        const hit = a.filter((g) => b.indexOf(g) >= 0);
        if (hit.length) rep.push('句 ' + (i + 1) + '-' + (i + 2) + ' 重复「' + hit.slice(0, 2).join(' / ') + '」');
      }
      if (rep.length) nat.push(rep.slice(0, 3).join('；') + (rep.length > 3 ? ' 等 ' + rep.length + ' 处' : ''));
      const zhStyle = String(body[key] || '').match(/\b(?:at|in|on)\s+(?:bad|good|wrong|right)\s+(?:time|times|moment|moments)\b/gi) || [];
      if (zhStyle.length) {
        const uniq = [];
        zhStyle.forEach((s) => { const t = s.toLowerCase().replace(/\s+/g, ' '); if (uniq.indexOf(t) < 0) uniq.push(t); });
        nat.push('疑似中式搭配：' + uniq.slice(0, 3).join(' / '));
      }
      const wrap = (String(body[key] || '').match(/\bin the end\s*,?/gi) || []).length;
      if (wrap > 1) nat.push('收尾套话 "In the end" 出现 ' + wrap + ' 次');
      if (nat.length) checks.push({ name: '自然度粗筛', status: 'warn', detail: nat.join('；') });
      else checks.push({ name: '自然度粗筛', status: 'pass', detail: '' });
    }
    /* 段落对齐（v1 · 2026-09-20）：这一项是「A1- 与其它档错位」的唯一机械拦截点。
       为什么必须单独有一项 ——
         ① 聚合层无条件把 >12 段 slice 回 12，所以 para_count **恒为 12**、
            「段数不一致」在最终产物里根本看不见 → 另取 para_clean_count（截断前）补上，
            否则「拆段 → 砍末段」这个头号失败模式仍会静默通过；
         ② nodeAgg 明确「4 档体系：每组 1 档，无需组内统一」，各档自报映射、互不校验；
         ③ ⑨ 大意复核明文「低档覆盖不全不算失败」。
       判据：align_map 是 4 档折算到同一 gist 轴后的映射，正常情况**恒等于 [[1],[2],…,[12]]**。
       任何合并 / 跳号 / 少一项，都意味着「第 i 段讲的不是第 i 条大意」→ 切档会跳位。 */
    {
      const am = JS(align_map, {});
      const pc = JS(para_count, {});
      const cc = JS(para_clean_count, {});
      const bad = [];
      const pure = Array.isArray(am[key]) ? am[key] : null;
      const pars = parseInt(pc[key], 10);
      if (pars !== 12) { bad.push('段数 ' + (isNaN(pars) ? '?' : pars) + '（应为 12）'); }
      const cleanN = parseInt(cc[key], 10);
      if (!isNaN(cleanN) && cleanN !== 12) {
        bad.push('模型原始段数 ' + cleanN + (cleanN > 12
          ? '（超过 12，聚合层已砍掉尾部 ' + (cleanN - 12) + ' 段，末段内容已丢失）'
          : '（不足 12，无法补齐）'));
      }
      if (!pure || pure.length !== 12) {
        bad.push('引用标注 ' + (pure ? pure.length : 0) + ' 项（应为 12）');
      } else {
        const off = [];
        for (let i = 0; i < 12; i++) {
          const ids = (pure[i] || []).map((x) => parseInt(x, 10));
          if (ids.indexOf(i + 1) < 0) { off.push('第' + (i + 1) + '段↔大意' + (i + 1) + '（实为 ' + JSON.stringify(ids) + '）'); }
        }
        if (off.length) { bad.push('错位 ' + off.length + ' 处：' + off.slice(0, 3).join('，')); }
      }
      if (bad.length) {
        fails.push('段落对齐: ' + LABEL[key] + ' ' + bad.join('；') + ' → 该档与其它档逐段错位，需重新生成');
        checks.push({ name: '段落对齐', status: 'fail', detail: bad.join('；') });
      } else {
        checks.push({ name: '段落对齐', status: 'pass', detail: '12 段 ↔ 12 条大意严格 1:1' });
      }
    }
    let idKeys = [];
    try { idKeys = Object.keys(JSON.parse(identity || '{}')); } catch (e) { }
    const need = ['theme', 'angle', 'shelf', 'fit', 'provenance'];
    const miss = need.filter((k) => idKeys.indexOf(k) < 0);
    if (miss.length) {
      fails.push('身份完整性: 缺少 ' + miss.join('/'));
      checks.push({ name: '身份完整性', status: 'fail', detail: miss.join('/') });
    } else {
      checks.push({ name: '身份完整性', status: 'pass', detail: '' });
    }
    checks.push({ name: '合规署名', status: 'pass', detail: '人工审核标记由发布环节补充' });
    return {
      level: LABEL[key], level_key: key, word_count: wc, word_range: lo + '-' + hi,
      msl: Math.round(msl * 10) / 10, msl_range: slo + '-' + shi,
      lexile_est: lex, lexile_range: (lxlo > 0 ? lxlo + '-' + lxhi : 'BR-' + lxhi),
      has_body: !!(body[key] && String(body[key]).trim()),
      score: checks.filter((c) => c.status === 'pass').length,
      pass: fails.length === 0, checks: checks, fail_reasons: fails
    };
  };

  const results = ALL.map((k) => validate(k, body[k]));
  const legKeys = { a2: 'A2', b1: 'B1', b2: 'B2' };
  const legacy = Object.keys(legKeys).map((k) => {
    const r = results.filter((x) => x.level_key === legKeys[k])[0];
    if (!r) return null;
    const c = JSON.parse(JSON.stringify(r)); c.level = k.toUpperCase(); c.level_key_legacy = legKeys[k]; return c;
  }).filter(Boolean);
  const overall = {
    total_checks: ALL.length * 11,
    total_pass: results.reduce((s, r) => s + r.score, 0),
    all_pass: results.every((r) => r.pass),
    levels: ALL.length,
    lexile_note: '蓝思为按平均句长 + 长词占比 + 平均词长估算，非 MetaMetrics 官方值，仅作档位一致性参考',
    results: results,
    results_legacy: legacy
  };
  return {
    validation_json: JSON.stringify(overall),
    validation_pass: String(overall.all_pass),
    validation_score: overall.total_pass + '/' + overall.total_checks
  };
}

